function fitContain(sw,sh,mw,mh){
  if(sw<=0||sh<=0) return {w:0,h:0};
  var r=Math.min(mw/sw, mh/sh);
  return { w:Math.max(1,Math.round(sw*r)), h:Math.max(1,Math.round(sh*r)) };
}
function fitCover(sw,sh,mw,mh){
  if(sw<=0||sh<=0) return {w:0,h:0};
  var r=Math.max(mw/sw, mh/sh);
  return { w:Math.max(1,Math.round(sw*r)), h:Math.max(1,Math.round(sh*r)) };
}
function cropRect(sw,sh,tw,th,anchor){
  anchor=anchor||"center";
  var sx=Math.max(0,(sw-tw)/2), sy=Math.max(0,(sh-th)/2);
  if(anchor==="topleft"){ sx=0; sy=0; }
  else if(anchor==="topright"){ sx=sw-tw; sy=0; }
  else if(anchor==="bottomleft"){ sx=0; sy=sh-th; }
  else if(anchor==="bottomright"){ sx=sw-tw; sy=sh-th; }
  return { x:Math.round(sx), y:Math.round(sy), w:Math.round(tw), h:Math.round(th) };
}
function scaleBy(w,h,f){ return { w:Math.max(1,Math.round(w*f)), h:Math.max(1,Math.round(h*f)) }; }
var EXPORTS={ fitContain:fitContain, fitCover:fitCover, cropRect:cropRect, scaleBy:scaleBy };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ImageResizeForgePure = EXPORTS; }
